import { useEffect } from "react";
import { createPortal } from "react-dom";

export interface PhotoLightboxProps {
  src: string;
  onClose: () => void;
}

/**
 * A photo on its own, filling the window.
 *
 * On a phone a print sits in half a page and its faces are too small to make
 * out; pinching the book magnifies the paper around it as much as the picture.
 * This gives the photo the whole screen first, and leaves pinch to go further.
 *
 * Rendered into `document.body` rather than in place: the book is mirrored with
 * a transform, and a transformed ancestor becomes the containing block for
 * `position: fixed`, so an overlay left inside it would come out back to front
 * and cropped to the page it came from.
 */
export function PhotoLightbox({ src, onClose }: PhotoLightboxProps) {
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        // The viewer's own Escape handling would leave fullscreen at the same
        // time, which is two dismissals for one press.
        event.stopPropagation();
        onClose();
      }
    };

    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [onClose]);

  return createPortal(
    <div
      className="ae-lightbox"
      role="dialog"
      aria-modal="true"
      aria-label="תמונה מוגדלת"
      onClick={onClose}
    >
      <img className="ae-lightbox__img" src={src} alt="" />
      <button type="button" className="ae-lightbox__close" aria-label="סגירה">
        ✕
      </button>
    </div>,
    document.body,
  );
}
